// Both triggers end here, so later nodes have one place to read the batch id from.
const batchId = $input.first().json.batch_id;
if (!batchId) throw new Error('No batch_id received');
return [{ json: { batch_id: batchId } }];

const users = $input.all().map(i => i.json).filter(u => u.user_id);
// Redirect every email to a test inbox we control (never the CSV address).
const aliases = String($env.APP_TEST_INBOX_ALIASES || '').split(',').map(s => s.trim()).filter(Boolean);
if (!aliases.length) throw new Error('Set TEST_INBOX_ALIASES in .env');

const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const rate = p => p.rate_min && p.rate_max ? `${p.rate_min}% – ${p.rate_max}% p.a.`
  : p.rate_min ? `from ${p.rate_min}% p.a.` : 'rate on request';
const inr = n => '₹' + Number(n).toLocaleString('en-IN');

return users.map((u, i) => {
  const first = (u.name || 'there').split(' ')[0];
  const products = u.products.slice(0, 10);
  const rows = products.map(p => `
    <tr>
      <td style="padding:10px;border-bottom:1px solid #eee"><strong>${esc(p.lender)}</strong><br>${esc(p.product)}</td>
      <td style="padding:10px;border-bottom:1px solid #eee;white-space:nowrap">${esc(rate(p))}</td>
      <td style="padding:10px;border-bottom:1px solid #eee;color:#555">${esc(p.reason)}</td>
    </tr>`).join('');
  const more = u.products.length > products.length ? `<p>…and ${u.products.length - products.length} more.</p>` : '';

  const html = `<div style="font-family:Arial,sans-serif;max-width:640px;color:#222">
    <h2 style="color:#1a5fb4">Hi ${esc(first)}, you may qualify for ${u.products.length} personal loan${u.products.length > 1 ? 's' : ''}</h2>
    <p>Based on your profile (${esc(u.employment_status)}, monthly income ${inr(u.monthly_income)}, credit score ${u.credit_score}),
       these lenders' published criteria look like a fit:</p>
    <table style="border-collapse:collapse;width:100%;font-size:14px">
      <tr style="background:#f3f6fb;text-align:left">
        <th style="padding:10px">Loan</th><th style="padding:10px">Interest</th><th style="padding:10px">Why it fits</th>
      </tr>${rows}
    </table>${more}
    <p style="font-size:12px;color:#888;margin-top:24px">Eligibility is indicative and based on criteria published by lenders;
       final approval is at the lender's discretion.<br>
       Demo notice: this email was redirected to a test inbox. Original recipient: ${esc(u.original_email)} · user ${esc(u.user_id)}</p>
  </div>`;

  return {
    json: {
      batch_id: u.batch_id,
      user_id: u.user_id,
      to: aliases[i % aliases.length],
      subject: `${first}, ${u.products.length} personal loan${u.products.length > 1 ? 's' : ''} you may qualify for`,
      html,
      matchIdsJson: JSON.stringify(u.match_ids),
    },
  };
});
